114	     *  year starts on 1 July, so July-December fall in the fiscal year ending the following
115	     *  calendar year, and January-June in the one ending the current year. */
116	    static int fiscalYearOf(java.time.LocalDate date) {
117	        return date.getMonthValue() >= java.time.Month.JULY.getValue()
118	                ? date.getYear() + 1 : date.getYear();
119	    }
120	
121	    /** A single Luhn check digit (0-9) computed over the digits contained in the
