124	        String code = owner.getCustomerCode();
125	        if (code == null) {
126	            return null;
127	        }
128	        int sum = 0;
129	        boolean dbl = true;
130	        for (int i = code.length() - 1; i >= 0; i--) {
131	            char c = code.charAt(i);
132	            if (c < '0' || c > '9') {
133	                continue;
134	            }
135	            int d = c - '0';
136	            if (dbl) {
137	                d *= 2;
138	                if (d > 9) {
139	                    d -= 9;
140	                }
141	            }
