151	     *  fiscal year starting 1 July). */
152	    default Integer membershipPoints(Owner owner) {
153	        int points = 0;
154	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
155	        if (hasEmail) {
156	            points += 2;
157	        }
158	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
