174	     *  {@code membershipLevelCap} when present, so a new owner's level cannot exceed one
175	     *  above the maximum among their household members at creation. */
176	    default Integer membershipLevel(Owner owner) {
177	        int level = uncappedMembershipLevel(owner);
178	        Integer cap = owner.getMembershipLevelCap();
179	        if (cap != null && level > cap) {
180	            return cap;
181	        }
182	        return level;
183	    }
