185	    /** The membership level derived purely from membershipPoints, before any
186	     *  household-derived ceiling is applied. */
187	    default Integer uncappedMembershipLevel(Owner owner) {
188	        int points = membershipPoints(owner);
189	        if (points <= 1) {
190	            return 1;
191	        }
192	        if (points <= 3) {
193	            return 2;
194	        }
195	        if (points <= 5) {
196	            return 3;
197	        }
198	        return 4;
199	    }
200	
